                while i < len(lines) and re.match(r'^[\*\-\+]\s+', lines[i]):
                    item = re.sub(r'^[\*\-\+]\s+', '', lines[i])
                    list_items.append(item)
                    i += 1
                blocks.append({'type': 'list', 'items': list_items, 'ordered': False})
            # Code blocks
            elif line.strip().startswith('```'):
                code_lines = []
                i += 1
                while i < len(lines) and not lines[i].strip().startswith('```'):
                    code_lines.append(lines[i])
                    i += 1
                i += 1  # skip closing ```
                blocks.append({'type': 'code', 'content': '\n'.join(code_lines)})
            # Empty lines
            elif line.strip() == '':
                i += 1
            # Paragraph
            else:
                para_lines = []
                while i < len(lines) and lines[i].strip() != '' and not any([
                    re.match(r'^#{1,6}\s+', lines[i]),
                    re.match(r'^[\*\-\+]\s+', lines[i]),
                    lines[i].strip().startswith('```'),
                ]):
                    para_lines.append(lines[i])
                    i += 1
                if para_lines:
                    blocks.append({'type': 'paragraph', 'content': ' '.join(para_lines)})

        return blocks

class InlineFormatter:
    """Format inline markdown elements"""

    @staticmethod
    def to_html(text: str) -> str:
        """Convert inline markdown to HTML"""
        # Handle code (don't process markdown inside code)
        code_map = {}
        text = re.sub(r'`([^`]+)`', lambda m: (code_map.setdefault(f'__CODE{len(code_map)}__', f'<code>{html_module.escape(m.group(1))}</code>'), f'__CODE{len(code_map)-1}__')[1], text)

        # Handle bold
        text = re.sub(r'\*\*([^*]+)\*\*', lambda m: f'<strong>{InlineFormatter.to_html(m.group(1))}</strong>', text)
        text = re.sub(r'__([^_]+)__', lambda m: f'<strong>{InlineFormatter.to_html(m.group(1))}</strong>', text)

        # Handle italic
        text = re.sub(r'\*([^*]+)\*', lambda m: f'<em>{InlineFormatter.to_html(m.group(1))}</em>', text)
        text = re.sub(r'_([^_]+)_', lambda m: f'<em>{InlineFormatter.to_html(m.group(1))}</em>', text)

        # Restore code blocks
        for key, val in code_map.items():
            text = text.replace(key, val)

        return text

