        self.rows = rows

# ============================================================================
# PARSERS
# ============================================================================

class MarkdownParser:
    """Parse Markdown to an AST-like structure"""

    def parse(self, text: str) -> List[Block]:
        """Parse markdown text into blocks"""
        blocks = []
        lines = text.split('\n')
        i = 0

        while i < len(lines):
            line = lines[i]

            # Skip empty lines
            if line.strip() == '':
                i += 1
                continue

            # Headers
            if match := re.match(r'^(#{1,6})\s+(.+)$', line):
                level = len(match.group(1))
                content = match.group(2).strip()
                blocks.append(Heading(level, content))
                i += 1

            # Horizontal rules
            elif re.match(r'^[\*\-_]{3,}$', line.strip()):
                blocks.append(HorizontalRule())
                i += 1

            # Code blocks (fenced)
            elif line.strip().startswith('```'):
                code_lines = []
                lang = line.strip()[3:].strip()
                i += 1
                while i < len(lines) and not lines[i].strip().startswith('```'):
                    code_lines.append(lines[i])
                    i += 1
                i += 1  # skip closing ```
                blocks.append(CodeBlock('\n'.join(code_lines), lang))

            # Bullet lists
            elif re.match(r'^[\*\-\+]\s+', line):
                items = []
                while i < len(lines) and re.match(r'^[\*\-\+]\s+', lines[i]):
                    item = re.sub(r'^[\*\-\+]\s+', '', lines[i]).strip()
                    items.append(item)
                    i += 1
                blocks.append(BulletList(items))

            # Ordered lists
            elif re.match(r'^\d+\.\s+', line):
                items = []
                while i < len(lines) and re.match(r'^\d+\.\s+', lines[i]):
                    item = re.sub(r'^\d+\.\s+', '', lines[i]).strip()
                    items.append(item)
                    i += 1
                blocks.append(OrderedList(items))

            # Block quotes
            elif line.strip().startswith('>'):
                quote_lines = []
                while i < len(lines) and lines[i].strip().startswith('>'):
                    quote_lines.append(re.sub(r'^>\s*', '', lines[i]))
                    i += 1
                blocks.append(BlockQuote(' '.join(quote_lines)))

            # Paragraph
            else:
                para_lines = []
                while i < len(lines) and lines[i].strip() != '' and not any([
                    re.match(r'^#{1,6}\s+', lines[i]),
                    re.match(r'^[\*\-\+]\s+', lines[i]),
                    re.match(r'^\d+\.\s+', lines[i]),
                    lines[i].strip().startswith('>'),
                    lines[i].strip().startswith('```'),
                    re.match(r'^[\*\-_]{3,}$', lines[i].strip()),
                ]):
                    para_lines.append(lines[i])
                    i += 1
                if para_lines:
                    blocks.append(Paragraph(' '.join(para_lines)))

        return blocks

class HTMLParser:
    """Parse HTML to Markdown"""

    def parse(self, text: str) -> List[Block]:
        """Parse HTML and convert to blocks"""
        # Simple HTML to markdown conversion
        blocks = []

        # Remove doctype and script tags
        text = re.sub(r'<!DOCTYPE[^>]*>', '', text, flags=re.IGNORECASE)
        text = re.sub(r'<script[^>]*>.*?</script>', '', text, flags=re.IGNORECASE | re.DOTALL)
        text = re.sub(r'<style[^>]*>.*?</style>', '', text, flags=re.IGNORECASE | re.DOTALL)
        text = re.sub(r'<[^>]*>', '', text)

        # Parse as markdown
        parser = MarkdownParser()
        return parser.parse(text)

# ============================================================================
