# CONVERTER
# ============================================================================

class PandocConverter:
    def __init__(self):
        self.from_format = 'markdown'
        self.to_format = 'html'
        self.standalone = False
        self.output_file = None
        self.input_files = []
        self.metadata = {}
        self.variables = {}

    def convert(self, input_text: str) -> str:
        """Main conversion method"""
        # Normalize format names
        from_fmt = self._normalize_format(self.from_format)
        to_fmt = self._normalize_format(self.to_format)

        # Parse input
        if from_fmt in ['markdown', 'markdown_github', 'markdown_mmd', 'markdown_phpextra', 'markdown_strict', 'gfm', 'commonmark', 'commonmark_x']:
            parser = MarkdownParser()
        elif from_fmt == 'html':
            parser = HTMLParser()
        else:
            # For other formats, try to parse as markdown as fallback
            parser = MarkdownParser()

        blocks = parser.parse(input_text)

        # Write output
        if to_fmt in ['html', 'html4', 'html5']:
            writer = HTMLWriter(standalone=self.standalone)
        elif to_fmt in ['markdown', 'markdown_github', 'markdown_mmd', 'markdown_phpextra', 'markdown_strict', 'gfm', 'commonmark', 'commonmark_x']:
            writer = MarkdownWriter()
        elif to_fmt in ['plain', 'text']:
            writer = PlaintextWriter()
        elif to_fmt in ['latex', 'beamer']:
            writer = LaTeXWriter()
        elif to_fmt == 'json':
            writer = JSONWriter()
        else:
            # Default to HTML for unknown formats
            writer = HTMLWriter(standalone=self.standalone)

        return writer.write(blocks)

    def _normalize_format(self, fmt: str) -> str:
        """Normalize format name"""
        fmt = fmt.lower().replace('_', '_')
        if fmt in ['markdown-github']:
            fmt = 'markdown_github'
        return fmt

