            code_map[key] = f'<code>{html_module.escape(m.group(1))}</code>'
            return key
        text = re.sub(r'`([^`]+)`', save_code, text)

        # Handle bold
        text = re.sub(r'\*\*([^*]+?)\*\*', r'<strong>\1</strong>', text)
        text = re.sub(r'__([^_]+?)__', r'<strong>\1</strong>', text)

        # Handle italic
        text = re.sub(r'\*([^*]+?)\*', r'<em>\1</em>', text)
        text = re.sub(r'_([^_]+?)_', r'<em>\1</em>', text)

        # Restore code
        for key, val in code_map.items():
            text = text.replace(key, val)

        return text

    @staticmethod
    def to_latex(text: str) -> str:
        """Convert inline markdown to LaTeX"""
        # Escape LaTeX special characters
        for char in ['\\', '{', '}', '$', '&', '#', '%', '_', '^', '~']:
            if char == '\\':
                text = text.replace('\\', '\\textbackslash{}')
            else:
                text = text.replace(char, '\\' + char)

        # Handle bold
        text = re.sub(r'\*\*([^*]+?)\*\*', r'\\textbf{\1}', text)
        text = re.sub(r'__([^_]+?)__', r'\\textbf{\1}', text)

        # Handle italic
        text = re.sub(r'\*([^*]+?)\*', r'\\textit{\1}', text)
        text = re.sub(r'_([^_]+?)_', r'\\textit{\1}', text)

        # Handle code
        text = re.sub(r'`([^`]+)`', r'\\texttt{\1}', text)

        # Handle links
        text = re.sub(r'\[([^\]]+)\]\(([^\)]+)\)', r'\\href{\2}{\1}', text)

        return text

    @staticmethod
    def to_plaintext(text: str) -> str:
        """Strip markdown formatting"""
        # Remove links
        text = re.sub(r'\[([^\]]+)\]\([^\)]+\)', r'\1', text)
        # Remove images
        text = re.sub(r'!\[([^\]]*)\]\([^\)]+\)', '', text)
        # Remove bold
        text = re.sub(r'\*\*([^*]+?)\*\*', r'\1', text)
        text = re.sub(r'__([^_]+?)__', r'\1', text)
        # Remove italic
        text = re.sub(r'\*([^*]+?)\*', r'\1', text)
        text = re.sub(r'_([^_]+?)_', r'\1', text)
        # Remove code
        text = re.sub(r'`([^`]+)`', r'\1', text)
        return text

