# ============================================================================
# DOCUMENT MODEL
# ============================================================================

class Block:
    """Base class for document blocks"""
    pass

class Heading(Block):
    def __init__(self, level: int, content: str):
        self.level = level
        self.content = content

class Paragraph(Block):
    def __init__(self, content: str):
        self.content = content

class CodeBlock(Block):
    def __init__(self, content: str, language: str = ''):
        self.content = content
        self.language = language

class BulletList(Block):
    def __init__(self, items: List[str]):
        self.items = items

class OrderedList(Block):
    def __init__(self, items: List[str]):
        self.items = items

class BlockQuote(Block):
    def __init__(self, content: str):
        self.content = content

class HorizontalRule(Block):
    pass

class Table(Block):
    def __init__(self, headers: List[str], rows: List[List[str]]):
        self.headers = headers
        self.rows = rows

# ============================================================================
# PARSERS
# ============================================================================

class MarkdownParser:
    """Parse Markdown to an AST-like structure"""

    def parse(self, text: str) -> List[Block]:
        """Parse markdown text into blocks"""
        blocks = []
        lines = text.split('\n')
        i = 0

        while i < len(lines):
            line = lines[i]

            # Skip empty lines
            if line.strip() == '':
                i += 1
                continue

            # Headers
            if match := re.match(r'^(#{1,6})\s+(.+)$', line):
                level = len(match.group(1))
                content = match.group(2).strip()
                blocks.append(Heading(level, content))
                i += 1

            # Horizontal rules
            elif re.match(r'^[\*\-_]{3,}$', line.strip()):
                blocks.append(HorizontalRule())
                i += 1

            # Code blocks (fenced)
            elif line.strip().startswith('```'):
                code_lines = []
                lang = line.strip()[3:].strip()
                i += 1
                while i < len(lines) and not lines[i].strip().startswith('```'):
                    code_lines.append(lines[i])
                    i += 1
                i += 1  # skip closing ```
                blocks.append(CodeBlock('\n'.join(code_lines), lang))

            # Bullet lists
            elif re.match(r'^[\*\-\+]\s+', line):
                items = []
                while i < len(lines) and re.match(r'^[\*\-\+]\s+', lines[i]):
                    item = re.sub(r'^[\*\-\+]\s+', '', lines[i]).strip()
                    items.append(item)
                    i += 1
                blocks.append(BulletList(items))

            # Ordered lists
            elif re.match(r'^\d+\.\s+', line):
                items = []
                while i < len(lines) and re.match(r'^\d+\.\s+', lines[i]):
                    item = re.sub(r'^\d+\.\s+', '', lines[i]).strip()
                    items.append(item)
                    i += 1
                blocks.append(OrderedList(items))

            # Block quotes
            elif line.strip().startswith('>'):
                quote_lines = []
                while i < len(lines) and lines[i].strip().startswith('>'):
                    quote_lines.append(re.sub(r'^>\s*', '', lines[i]))
                    i += 1
                blocks.append(BlockQuote(' '.join(quote_lines)))

            # Paragraph
            else:
                para_lines = []
                while i < len(lines) and lines[i].strip() != '' and not any([
                    re.match(r'^#{1,6}\s+', lines[i]),
                    re.match(r'^[\*\-\+]\s+', lines[i]),
                    re.match(r'^\d+\.\s+', lines[i]),
                    lines[i].strip().startswith('>'),
                    lines[i].strip().startswith('```'),
                    re.match(r'^[\*\-_]{3,}$', lines[i].strip()),
                ]):
                    para_lines.append(lines[i])
                    i += 1
                if para_lines:
                    blocks.append(Paragraph(' '.join(para_lines)))

        return blocks

class HTMLParser:
    """Parse HTML to Markdown"""

    def parse(self, text: str) -> List[Block]:
        """Parse HTML and convert to blocks"""
        # Simple HTML to markdown conversion
        blocks = []

        # Remove doctype and script tags
        text = re.sub(r'<!DOCTYPE[^>]*>', '', text, flags=re.IGNORECASE)
        text = re.sub(r'<script[^>]*>.*?</script>', '', text, flags=re.IGNORECASE | re.DOTALL)
        text = re.sub(r'<style[^>]*>.*?</style>', '', text, flags=re.IGNORECASE | re.DOTALL)
        text = re.sub(r'<[^>]*>', '', text)

        # Parse as markdown
        parser = MarkdownParser()
        return parser.parse(text)

# ============================================================================
# INLINE FORMATTERS
# ============================================================================

class InlineFormatter:
    """Format inline markdown elements"""

    @staticmethod
    def to_html(text: str) -> str:
        """Convert inline markdown to HTML"""
        if not text:
            return text

        # Escape HTML first (but preserve already-escaped content)
        # Handle links [text](url)
        text = re.sub(r'\[([^\]]+)\]\(([^\)]+)\)', r'<a href="\2">\1</a>', text)

        # Handle images ![alt](url)
        text = re.sub(r'!\[([^\]]*)\]\(([^\)]+)\)', r'<img src="\2" alt="\1" />', text)

        # Handle code (with placeholder to prevent further processing)
        code_map = {}
        def save_code(m):
            key = f'__CODE{len(code_map)}__'
            code_map[key] = f'<code>{html_module.escape(m.group(1))}</code>'
            return key
        text = re.sub(r'`([^`]+)`', save_code, text)

        # Handle bold
        text = re.sub(r'\*\*([^*]+?)\*\*', r'<strong>\1</strong>', text)
        text = re.sub(r'__([^_]+?)__', r'<strong>\1</strong>', text)

        # Handle italic
        text = re.sub(r'\*([^*]+?)\*', r'<em>\1</em>', text)
        text = re.sub(r'_([^_]+?)_', r'<em>\1</em>', text)

        # Restore code
        for key, val in code_map.items():
            text = text.replace(key, val)

        return text

    @staticmethod
    def to_latex(text: str) -> str:
        """Convert inline markdown to LaTeX"""
        # Escape LaTeX special characters
        for char in ['\\', '{', '}', '$', '&', '#', '%', '_', '^', '~']:
            if char == '\\':
                text = text.replace('\\', '\\textbackslash{}')
            else:
                text = text.replace(char, '\\' + char)

        # Handle bold
        text = re.sub(r'\*\*([^*]+?)\*\*', r'\\textbf{\1}', text)
        text = re.sub(r'__([^_]+?)__', r'\\textbf{\1}', text)

        # Handle italic
        text = re.sub(r'\*([^*]+?)\*', r'\\textit{\1}', text)
        text = re.sub(r'_([^_]+?)_', r'\\textit{\1}', text)

        # Handle code
        text = re.sub(r'`([^`]+)`', r'\\texttt{\1}', text)

        # Handle links
        text = re.sub(r'\[([^\]]+)\]\(([^\)]+)\)', r'\\href{\2}{\1}', text)

        return text

    @staticmethod
    def to_plaintext(text: str) -> str:
        """Strip markdown formatting"""
        # Remove links
        text = re.sub(r'\[([^\]]+)\]\([^\)]+\)', r'\1', text)
        # Remove images
        text = re.sub(r'!\[([^\]]*)\]\([^\)]+\)', '', text)
        # Remove bold
        text = re.sub(r'\*\*([^*]+?)\*\*', r'\1', text)
        text = re.sub(r'__([^_]+?)__', r'\1', text)
        # Remove italic
        text = re.sub(r'\*([^*]+?)\*', r'\1', text)
        text = re.sub(r'_([^_]+?)_', r'\1', text)
        # Remove code
        text = re.sub(r'`([^`]+)`', r'\1', text)
        return text

# ============================================================================
