    def parse(self, text: str) -> List[Block]:
        """Parse markdown text into blocks"""
        blocks = []
        lines = text.split('\n')
        i = 0

        while i < len(lines):
            line = lines[i]

            # Skip empty lines
            if line.strip() == '':
                i += 1
                continue

            # Headers
            if match := re.match(r'^(#{1,6})\s+(.+)$', line):
