                for i, item in enumerate(block.items, 1):
                    result.append(f'{i}. {item}')
            elif isinstance(block, BlockQuote):
                result.append('> ' + block.content)
            elif isinstance(block, HorizontalRule):
                result.append('---')
        return '\n\n'.join(result)

class PlaintextWriter(Writer):
    """Write documents as plain text"""

    def write(self, blocks: List[Block]) -> str:
        """Convert blocks to plain text"""
        result = []
        for block in blocks:
            if isinstance(block, Heading):
                result.append(block.content)
            elif isinstance(block, Paragraph):
                content = InlineFormatter.to_plaintext(block.content)
                result.append(content)
            elif isinstance(block, CodeBlock):
                result.append(block.content)
            elif isinstance(block, BulletList):
                for item in block.items:
                    result.append('  ' + item)
            elif isinstance(block, OrderedList):
                for i, item in enumerate(block.items, 1):
                    result.append(f'  {i}. {item}')
            elif isinstance(block, BlockQuote):
                result.append(block.content)
        return '\n'.join(result)

class LaTeXWriter(Writer):
    """Write documents in LaTeX format"""

    def write(self, blocks: List[Block]) -> str:
        """Convert blocks to LaTeX"""
        result = []
        for block in blocks:
            if isinstance(block, Heading):
                level = min(block.level - 1, 2)
                commands = ['section', 'subsection', 'subsubsection']
                cmd = commands[level]
                content = block.content
                text_id = content.lower().replace(' ', '-')
                result.append(f'\\{cmd}{{{content}}}\\label{{{text_id}}}')
            elif isinstance(block, Paragraph):
                content = InlineFormatter.to_latex(block.content)
                result.append(content)
            elif isinstance(block, CodeBlock):
                result.append('\\begin{verbatim}')
                result.append(block.content)
                result.append('\\end{verbatim}')
            elif isinstance(block, BulletList):
                result.append('\\begin{itemize}')
                for item in block.items:
                    result.append(f'\\item {item}')
                result.append('\\end{itemize}')
            elif isinstance(block, OrderedList):
                result.append('\\begin{enumerate}')
                for item in block.items:
                    result.append(f'\\item {item}')
                result.append('\\end{enumerate}')
        return '\n\n'.join(result)

class JSONWriter(Writer):
    """Write documents as JSON"""

    def write(self, blocks: List[Block]) -> str:
        """Convert blocks to JSON"""
        data = []
        for block in blocks:
            if isinstance(block, Heading):
                data.append({'t': 'Header', 'c': [block.level, [block.content]]})
            elif isinstance(block, Paragraph):
                data.append({'t': 'Para', 'c': [{'t': 'Str', 'c': block.content}]})
            # Simplified JSON output
        return json.dumps(data, indent=2)

# ============================================================================
# CONVERTER
# ============================================================================

class PandocConverter:
    def __init__(self):
        self.from_format = 'markdown'
        self.to_format = 'html'
        self.standalone = False
        self.output_file = None
        self.input_files = []
        self.metadata = {}
        self.variables = {}

    def convert(self, input_text: str) -> str:
        """Main conversion method"""
        # Normalize format names
        from_fmt = self._normalize_format(self.from_format)
        to_fmt = self._normalize_format(self.to_format)

        # Parse input
        if from_fmt in ['markdown', 'markdown_github', 'markdown_mmd', 'markdown_phpextra', 'markdown_strict', 'gfm', 'commonmark', 'commonmark_x']:
            parser = MarkdownParser()
        elif from_fmt == 'html':
            parser = HTMLParser()
        else:
            # For other formats, try to parse as markdown as fallback
            parser = MarkdownParser()

        blocks = parser.parse(input_text)

        # Write output
        if to_fmt in ['html', 'html4', 'html5']:
            writer = HTMLWriter(standalone=self.standalone)
        elif to_fmt in ['markdown', 'markdown_github', 'markdown_mmd', 'markdown_phpextra', 'markdown_strict', 'gfm', 'commonmark', 'commonmark_x']:
            writer = MarkdownWriter()
        elif to_fmt in ['plain', 'text']:
            writer = PlaintextWriter()
        elif to_fmt in ['latex', 'beamer']:
            writer = LaTeXWriter()
        elif to_fmt == 'json':
            writer = JSONWriter()
        else:
            # Default to HTML for unknown formats
            writer = HTMLWriter(standalone=self.standalone)

        return writer.write(blocks)

    def _normalize_format(self, fmt: str) -> str:
        """Normalize format name"""
        fmt = fmt.lower().replace('_', '_')
        if fmt in ['markdown-github']:
            fmt = 'markdown_github'
        return fmt

