class Writer:
    """Base writer class"""

    def write(self, blocks: List[Block]) -> str:
        raise NotImplementedError

class HTMLWriter(Writer):
    """Write documents in HTML format"""

    def __init__(self, standalone: bool = False, template: Optional[str] = None):
        self.standalone = standalone
        self.template = template

    def write(self, blocks: List[Block]) -> str:
        """Convert blocks to HTML"""
        result = []

        for block in blocks:
            if isinstance(block, Heading):
                level = block.level
                content = InlineFormatter.to_html(block.content)
                # Generate ID from content
                text_id = re.sub(r'<[^>]+>', '', content).lower()
                text_id = re.sub(r'[^a-z0-9\-]', '-', text_id)
                text_id = re.sub(r'-+', '-', text_id).strip('-')
                result.append(f'<h{level} id="{text_id}">{content}</h{level}>')

            elif isinstance(block, Paragraph):
                content = InlineFormatter.to_html(block.content)
                result.append(f'<p>{content}</p>')

            elif isinstance(block, CodeBlock):
                content = html_module.escape(block.content)
                if block.language:
                    result.append(f'<pre><code class="language-{html_module.escape(block.language)}">{content}\n</code></pre>')
                else:
                    result.append(f'<pre><code>{content}\n</code></pre>')

            elif isinstance(block, BulletList):
                result.append('<ul>')
                for item in block.items:
                    content = InlineFormatter.to_html(item)
                    result.append(f'<li>{content}</li>')
                result.append('</ul>')

            elif isinstance(block, OrderedList):
                result.append('<ol>')
                for item in block.items:
                    content = InlineFormatter.to_html(item)
                    result.append(f'<li>{content}</li>')
                result.append('</ol>')

            elif isinstance(block, BlockQuote):
                content = InlineFormatter.to_html(block.content)
                result.append(f'<blockquote>\n<p>{content}</p>\n</blockquote>')

            elif isinstance(block, HorizontalRule):
                result.append('<hr />')

            elif isinstance(block, Table):
                result.append('<table>')
                result.append('<thead><tr>')
                for header in block.headers:
                    result.append(f'<th>{html_module.escape(header)}</th>')
                result.append('</tr></thead>')
                result.append('<tbody>')
                for row in block.rows:
                    result.append('<tr>')
                    for cell in row:
                        result.append(f'<td>{html_module.escape(cell)}</td>')
                    result.append('</tr>')
                result.append('</tbody>')
                result.append('</table>')

        html_content = '\n'.join(result)

        if self.standalone:
            return self._wrap_standalone(html_content)
        return html_content

    def _wrap_standalone(self, content: str) -> str:
        """Wrap content in full HTML document"""
        css = self._get_default_css()
        return f"""<!DOCTYPE html>
<html xmlns="http://www.w3.org/1999/xhtml">
<head>
  <meta charset="utf-8" />
  <meta name="generator" content="pandoc" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=yes" />
  <title>test</title>
  <style>
{textwrap.indent(css, '    ')}
  </style>
</head>
<body>
{textwrap.indent(content, '')}
</body>
</html>"""

