def main():
    parser = argparse.ArgumentParser(
        prog='executable',
        add_help=False,
        usage='%(prog)s [OPTIONS] [FILES]'
    )

    # Format options
    parser.add_argument('-f', '--from', dest='from_format', default=None, metavar='FORMAT')
    parser.add_argument('-r', dest='from_format_alt', metavar='FORMAT')
    parser.add_argument('-t', '--to', dest='to_format', default=None, metavar='FORMAT')
    parser.add_argument('-w', dest='to_format_alt', metavar='FORMAT')

    # File options
    parser.add_argument('-o', '--output', dest='output_file', default=None, metavar='FILE')
    parser.add_argument('--data-dir', dest='data_dir', default=None, metavar='DIRECTORY')

    # Metadata and variables
    parser.add_argument('-M', '--metadata', dest='metadata', action='append', default=[], metavar='KEY[:VALUE]')
    parser.add_argument('--metadata-file', dest='metadata_file', default=None, metavar='FILE')
    parser.add_argument('-d', '--defaults', dest='defaults', default=None, metavar='FILE')
    parser.add_argument('--file-scope', dest='file_scope', action='store_true')
    parser.add_argument('--sandbox', dest='sandbox', action='store_true')

    # Document options
    parser.add_argument('-s', '--standalone', dest='standalone', action='store_true')
    parser.add_argument('--template', dest='template', default=None, metavar='FILE')
    parser.add_argument('-V', '--variable', dest='variables', action='append', default=[], metavar='KEY[:VALUE]')
    parser.add_argument('--variable-json', dest='variable_json', action='append', default=[], metavar='KEY[:JSON]')
    parser.add_argument('--wrap', dest='wrap', default=None, metavar='auto|none|preserve')
    parser.add_argument('--ascii', dest='ascii', action='store_true')
    parser.add_argument('--toc', '--table-of-contents', dest='toc', action='store_true')
    parser.add_argument('--toc-depth', dest='toc_depth', type=int, default=3, metavar='NUMBER')
    parser.add_argument('--lof', '--list-of-figures', dest='lof', action='store_true')
    parser.add_argument('--lot', '--list-of-tables', dest='lot', action='store_true')
    parser.add_argument('-N', '--number-sections', dest='number_sections', action='store_true')
    parser.add_argument('--number-offset', dest='number_offset', default=None, metavar='NUMBERS')
    parser.add_argument('--top-level-division', dest='top_level_division', default='section', metavar='section|chapter|part')
    parser.add_argument('--extract-media', dest='extract_media', default=None, metavar='PATH')
    parser.add_argument('--resource-path', dest='resource_path', default=None, metavar='SEARCHPATH')

