class MarkdownWriter(Writer):
    """Write documents in markdown format"""

    def write(self, blocks: List[Block]) -> str:
        """Convert blocks to markdown"""
        result = []
        for block in blocks:
            if isinstance(block, Heading):
                result.append('#' * block.level + ' ' + block.content)
            elif isinstance(block, Paragraph):
                result.append(block.content)
            elif isinstance(block, CodeBlock):
                if block.language:
                    result.append(f'```{block.language}\n{block.content}\n```')
                else:
                    result.append(f'```\n{block.content}\n```')
            elif isinstance(block, BulletList):
                for item in block.items:
                    result.append('- ' + item)
            elif isinstance(block, OrderedList):
                for i, item in enumerate(block.items, 1):
                    result.append(f'{i}. {item}')
            elif isinstance(block, BlockQuote):
                result.append('> ' + block.content)
            elif isinstance(block, HorizontalRule):
                result.append('---')
        return '\n\n'.join(result)

class PlaintextWriter(Writer):
    """Write documents as plain text"""

    def write(self, blocks: List[Block]) -> str:
        """Convert blocks to plain text"""
        result = []
        for block in blocks:
            if isinstance(block, Heading):
                result.append(block.content)
            elif isinstance(block, Paragraph):
                content = InlineFormatter.to_plaintext(block.content)
                result.append(content)
            elif isinstance(block, CodeBlock):
                result.append(block.content)
            elif isinstance(block, BulletList):
                for item in block.items:
                    result.append('  ' + item)
            elif isinstance(block, OrderedList):
                for i, item in enumerate(block.items, 1):
                    result.append(f'  {i}. {item}')
            elif isinstance(block, BlockQuote):
                result.append(block.content)
        return '\n'.join(result)

class LaTeXWriter(Writer):
    """Write documents in LaTeX format"""

    def write(self, blocks: List[Block]) -> str:
        """Convert blocks to LaTeX"""
        result = []
        for block in blocks:
            if isinstance(block, Heading):
                level = min(block.level - 1, 2)
                commands = ['section', 'subsection', 'subsubsection']
                cmd = commands[level]
                content = block.content
                text_id = content.lower().replace(' ', '-')
                result.append(f'\\{cmd}{{{content}}}\\label{{{text_id}}}')
            elif isinstance(block, Paragraph):
                content = InlineFormatter.to_latex(block.content)
                result.append(content)
            elif isinstance(block, CodeBlock):
                result.append('\\begin{verbatim}')
                result.append(block.content)
                result.append('\\end{verbatim}')
            elif isinstance(block, BulletList):
                result.append('\\begin{itemize}')
                for item in block.items:
                    result.append(f'\\item {item}')
                result.append('\\end{itemize}')
            elif isinstance(block, OrderedList):
                result.append('\\begin{enumerate}')
                for item in block.items:
                    result.append(f'\\item {item}')
                result.append('\\end{enumerate}')
        return '\n\n'.join(result)

class JSONWriter(Writer):
    """Write documents as JSON"""

    def write(self, blocks: List[Block]) -> str:
        """Convert blocks to JSON"""
        data = []
        for block in blocks:
            if isinstance(block, Heading):
                data.append({'t': 'Header', 'c': [block.level, [block.content]]})
            elif isinstance(block, Paragraph):
                data.append({'t': 'Para', 'c': [{'t': 'Str', 'c': block.content}]})
            # Simplified JSON output
        return json.dumps(data, indent=2)

