    to_fmt = args.to_format or args.to_format_alt or 'html'

    # Guess from file extensions if not specified
    if args.files and not args.from_format and not args.from_format_alt:
        ext = Path(args.files[0]).suffix.lstrip('.')
        ext_map = {
            'md': 'markdown', 'markdown': 'markdown',
            'html': 'html', 'htm': 'html',
            'tex': 'latex', 'latex': 'latex',
            'txt': 'markdown',
        }
        from_fmt = ext_map.get(ext, 'markdown')

    if args.output_file and not args.to_format and not args.to_format_alt:
        ext = Path(args.output_file).suffix.lstrip('.')
        ext_map = {
            'html': 'html', 'htm': 'html',
            'tex': 'latex', 'latex': 'latex',
            'md': 'markdown', 'markdown': 'markdown',
            'txt': 'plain',
        }
        to_fmt = ext_map.get(ext, 'html')

    converter.from_format = from_fmt
    converter.to_format = to_fmt
    converter.standalone = args.standalone
    converter.output_file = args.output_file
    converter.input_files = args.files

    # Read input
    if args.files:
        try:
            input_text = '\n\n'.join(Path(f).read_text() for f in args.files)
        except Exception as e:
            print(f"Error reading files: {e}", file=sys.stderr)
            sys.exit(1)
    else:
        input_text = sys.stdin.read()

    # Convert
    try:
        output = converter.convert(input_text)
    except Exception as e:
        if args.verbose:
            print(f"Error during conversion: {e}", file=sys.stderr)
        sys.exit(1)

    # Write output
    if args.output_file:
        try:
            Path(args.output_file).write_text(output)
        except Exception as e:
            print(f"Error writing output: {e}", file=sys.stderr)
            sys.exit(1)
    else:
        print(output, end='')

